 1	#ifndef RUNNER_TE_SYNC_H
 2	#define RUNNER_TE_SYNC_H
 3	
 4	#include <stdint.h>
 5	
 6	#ifdef __cplusplus
 7	extern "C" {
 8	#endif
 9	
10	/* Times a push to the panel's refresh. The AMOLED scans its memory top to
11	 * bottom 60 times a second, and a full push takes about two refreshes, so a
12	 * push that starts at a random moment shows two pictures at once, with a seam
13	 * between them: a thin line that moved a few pixels can fall in the gap and
14	 * vanish for a frame. The panel's TE line pulses once a refresh. Starting a
15	 * push at the same point in every cycle puts the seam where it is chosen, and
16	 * the right point keeps the write ahead of the scan so there is none.
17	 *
18	 * An interrupt feeds it the edges of TE with the microsecond they arrived; the
19	 * main loop asks how long to wait. Times are 32-bit microseconds that may
20	 * wrap. */
21	typedef struct {
22	  volatile uint32_t last_rise_us;
23	  volatile uint32_t period_us; /* 0 until two rising edges one period apart */
24	  volatile uint32_t rises;     /* rising edges accepted, saturating at 2 */
25	  uint32_t offset_us;
26	  uint32_t timeout_us;
27	} TeSync;
28	
29	/* A rising edge this soon after the last, or later than the longest period
30	 * that can be a missed edge, is not a refresh. */
31	#define TE_SYNC_MIN_PERIOD_US 8000u
32	#define TE_SYNC_MAX_PERIOD_US 33000u
33	
34	/* offset_us is how long after a rising edge a push should start. When no edge
35	 * has arrived for timeout_us the panel is taken to have stopped pulsing and
36	 * waiting is switched off, so a dead line cannot hang the display. */
37	void te_sync_init(TeSync *s, uint32_t offset_us, uint32_t timeout_us);
38	
39	/* One edge of the TE line (level 1 is a rising edge) at now_us. Called from an
40	 * interrupt, so on the device it lives in IRAM and uses nothing in flash. */
41	#if defined(ESP_PLATFORM)
42	#include "esp_attr.h"
43	#define TE_SYNC_ISR IRAM_ATTR
44	#else
45	#define TE_SYNC_ISR
46	#endif
47	void TE_SYNC_ISR te_sync_edge(TeSync *s, uint32_t now_us, int level);
48	
49	/* The refresh period learnt so far, or 0. */
50	uint32_t te_sync_period_us(const TeSync *s);
51	
52	/* Microseconds from now_us until a push should start: less than one period,
53	 * and 0 when the period is unknown or the edges have stopped. */
54	uint32_t te_sync_wait_us(const TeSync *s, uint32_t now_us);
55	
56	#ifdef __cplusplus
57	}
58	#endif
59	
60	#endif
 1	#include "runner/te_sync.h"
 2	
 3	void te_sync_init(TeSync *s, uint32_t offset_us, uint32_t timeout_us) {
 4	  s->last_rise_us = 0;
 5	  s->period_us = 0;
 6	  s->rises = 0;
 7	  s->offset_us = offset_us;
 8	  s->timeout_us = timeout_us;
 9	}
10	
11	void TE_SYNC_ISR te_sync_edge(TeSync *s, uint32_t now_us, int level) {
12	  if (!level) return;
13	  if (s->rises == 0) {
14	    s->last_rise_us = now_us;
15	    s->rises = 1;
16	    return;
17	  }
18	  const uint32_t gap = now_us - s->last_rise_us;
19	  if (gap < TE_SYNC_MIN_PERIOD_US) return; /* a glitch: keep the true edge */
20	
21	  const uint32_t period = s->period_us;
22	  if (gap <= TE_SYNC_MAX_PERIOD_US) {
23	    /* an eighth of the way to each new gap, so a slow drift is followed */
24	    if (!period)
25	      s->period_us = gap;
26	    else if (gap >= period)
27	      s->period_us = period + (gap - period) / 8;
28	    else
29	      s->period_us = period - (period - gap) / 8;
30	    s->rises = 2;
31	  } else if (period) {
32	    /* Edges the interrupt missed leave a whole number of periods; anything
33	     * else is a restart, and the period is learnt again. */
34	    const uint32_t k = (gap + period / 2) / period;
35	    const uint32_t off = gap > k * period ? gap - k * period : k * period - gap;
36	    if (k < 2 || off > period / 16) {
37	      s->period_us = 0;
38	      s->rises = 1;
39	    }
40	  } else {
41	    s->rises = 1;
42	  }
43	  s->last_rise_us = now_us;
44	}
45	
46	uint32_t te_sync_period_us(const TeSync *s) { return s->period_us; }
47	
48	uint32_t te_sync_wait_us(const TeSync *s, uint32_t now_us) {
49	  const uint32_t period = s->period_us;
50	  if (!period) return 0;
51	  uint32_t since = now_us - s->last_rise_us;
52	  if ((int32_t)since < 0) since = 0; /* the edge landed just after now was read */
53	  if (since > s->timeout_us) return 0;
54	  const uint32_t into = since % period;
55	  const uint32_t offset = s->offset_us % period;
56	  return into <= offset ? offset - into : period - into + offset;
57	}

