  1	/* Build with -DTE_DIAG to log, every few seconds, the TE period and where in
  2	 * the cycle each full push starts and flushes. */
  3	static const int kTeRing = 512;
  4	static volatile uint32_t teAt[kTeRing];
  5	static volatile uint8_t teLevel[kTeRing];
  6	static volatile uint32_t teHead;
  7	static const int kPushLog = 64;
  8	static uint32_t pushStart[kPushLog], pushFlush[kPushLog], pushEnd[kPushLog];
  9	static int pushCount;
 10	static uint32_t flushBeganUs;
 11	static uint32_t teReportedHead;
 12	#endif
 13	
 14	static void IRAM_ATTR teIsr() {
 15	  const uint32_t now = (uint32_t)esp_timer_get_time();
 16	  const int level = gpio_get_level((gpio_num_t)kPinTE);
 17	  te_sync_edge(&teSync, now, level);
 18	#ifdef TE_DIAG
 19	  uint32_t i = teHead;
 20	  teAt[i % kTeRing] = now;
 21	  teLevel[i % kTeRing] = (uint8_t)level;
 22	  teHead = i + 1;
 23	#endif
 24	}
 25	
 26	static void teInit() {
 27	  te_sync_init(&teSync, kTeSyncOffsetUs, kTeTimeoutUs);
 28	  pinMode(kPinTE, INPUT);
 29	  attachInterrupt(kPinTE, teIsr, CHANGE);
 30	}
