132	void loop() {
133	  M5.update();
134	  if (!pollButtons()) pollRotation();
135	  pollTouch();
136	  pollBattery();
137	
138	  uint32_t t0 = micros();
139	  unsigned long delayUs = runner_step(runner);
140	  uint32_t t1 = micros();
141	  present();
142	  uint32_t t2 = micros();
143	  frames++;
144	  overlay_frame(&overlay, millis());
145	  stepUs += t1 - t0;
146	  pushUs += t2 - t1;
147	
148	  /* Only the push counts against the delay. A hack's delay is the pause after
149	   * it draws, so a hack that asks for a one-second hold must still get it
150	   * however long its own step took. */
151	  unsigned long waitUsTarget = runner_remaining_delay_us(delayUs, t2 - t1);
152	  uint32_t waitedUs = 0;
153	  bool switched = false;
154	  while (!switched && waitedUs < waitUsTarget) {
155	    uint32_t slice =
156	        waitUsTarget - waitedUs < kSliceUs ? waitUsTarget - waitedUs : kSliceUs;
157	    delayMicroseconds(slice);
158	    waitedUs += slice;
159	    M5.update();
160	    switched = pollButtons() || pollRotation();
161	    if (!switched) {
162	      pollTouch();
163	      pollBattery();
164	    }
165	    if (!switched && overlay_wants_redraw(&overlay, millis())) present();
166	  }
167	  if (!switched) waitUs += micros() - t2;
168	
169	  if (millis() - statsAt >= kStatsEveryMs) {
170	    printStats("run");
171	#ifdef TE_DIAG
172	    teReport();
173	#endif
174	    resetStats();
175	  }
