143	  frames++;
144	  overlay_frame(&overlay, millis());
145	  stepUs += t1 - t0;
146	  pushUs += t2 - t1;
147	
148	  /* Only the push counts against the delay. A hack's delay is the pause after
149	   * it draws, so a hack that asks for a one-second hold must still get it
150	   * however long its own step took. */
151	  unsigned long waitUsTarget = runner_remaining_delay_us(delayUs, t2 - t1);
152	  uint32_t waitedUs = 0;
153	  bool switched = false;
154	  while (!switched && waitedUs < waitUsTarget) {
155	    uint32_t slice =
156	        waitUsTarget - waitedUs < kSliceUs ? waitUsTarget - waitedUs : kSliceUs;
157	    delayMicroseconds(slice);
158	    waitedUs += slice;
