164	    }
165	    if (!switched && overlay_wants_redraw(&overlay, millis())) present();
166	  }
167	  if (!switched) waitUs += micros() - t2;
168	
169	  if (millis() - statsAt >= kStatsEveryMs) {
170	    printStats("run");
171	#ifdef TE_DIAG
172	    teReport();
173	#endif
174	    resetStats();
175	  }
